COMMIT;
DO $test$ DECLARE h text; a jsonb; b jsonb; BEGIN
 h:=private.financial_operation_hash('sale.credit',private.canonical_financial_request_v1('sale.credit','{"cash_session_id":"lab-cash-a","customer_id":"lab-customer-2","sale":{"id":"lab-credit-2","subtotal":20,"total":20,"payment_method":"credit","amount_paid":0,"balance_due":20,"change_amount":0,"customer_id":"lab-customer-2","metadata":{"cloudInventoryEffects":true}},"items":[{"id":"lab-credit-2-item","product_id":"lab-credit-product-2","product_name":"Synthetic credit product 2","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[],"restaurant_settlement":{"parent_order_id":"lab-credit-2","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb),'admin:00000000-0000-0000-0000-0000000000aa','lab-cash-a','lab-station-a');
 a:=public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-credit-key-2',h,'sale.credit','{"cash_session_id":"lab-cash-a","customer_id":"lab-customer-2","sale":{"id":"lab-credit-2","subtotal":20,"total":20,"payment_method":"credit","amount_paid":0,"balance_due":20,"change_amount":0,"customer_id":"lab-customer-2","metadata":{"cloudInventoryEffects":true}},"items":[{"id":"lab-credit-2-item","product_id":"lab-credit-product-2","product_name":"Synthetic credit product 2","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[],"restaurant_settlement":{"parent_order_id":"lab-credit-2","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb);
 b:=public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-credit-key-2',h,'sale.credit','{"cash_session_id":"lab-cash-a","customer_id":"lab-customer-2","sale":{"id":"lab-credit-2","subtotal":20,"total":20,"payment_method":"credit","amount_paid":0,"balance_due":20,"change_amount":0,"customer_id":"lab-customer-2","metadata":{"cloudInventoryEffects":true}},"items":[{"id":"lab-credit-2-item","product_id":"lab-credit-product-2","product_name":"Synthetic credit product 2","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[],"restaurant_settlement":{"parent_order_id":"lab-credit-2","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb);
 IF a IS DISTINCT FROM b OR (a->>'success')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'CREDIT_RECEIPT_MISMATCH'; END IF;
 BEGIN PERFORM public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-credit-key-other',h,'sale.credit','{"cash_session_id":"lab-cash-a","customer_id":"lab-customer-2","sale":{"id":"lab-credit-2","subtotal":20,"total":20,"payment_method":"credit","amount_paid":0,"balance_due":20,"change_amount":0,"customer_id":"lab-customer-2","metadata":{"cloudInventoryEffects":true}},"items":[{"id":"lab-credit-2-item","product_id":"lab-credit-product-2","product_name":"Synthetic credit product 2","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[],"restaurant_settlement":{"parent_order_id":"lab-credit-2","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb); RAISE EXCEPTION 'CREDIT_DUPLICATE_SETTLEMENT'; EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM NOT IN ('RESTAURANT_ORDER_ALREADY_PAID','RESTAURANT_ORDER_NOT_ACTIVE') THEN RAISE; END IF; END;
 IF (SELECT debt FROM public.pos_customers WHERE id='lab-customer-2')<>20 OR (SELECT stock FROM public.pos_products WHERE id='lab-credit-product-2')<>18 OR (SELECT count(*) FROM public.pos_customer_ledger WHERE customer_id='lab-customer-2')<>1 OR (SELECT count(*) FROM public.pos_sales WHERE id='lab-credit-2')<>1 THEN RAISE EXCEPTION 'CREDIT_DUPLICATED_EFFECTS'; END IF;
END $test$;
SELECT 'PASS_FULL_CREDIT_REPLAY_AND_SECOND_SETTLEMENT' result;